        header=row();header.setPadding(dp(18),dp(8),dp(12),dp(5));TextView brand=button("↖",this::goBack);brand.setTextSize(22);brand.setBackgroundColor(Color.TRANSPARENT);header.addView(brand,new LinearLayout.LayoutParams(dp(48),dp(48)));title=text("DeckLab",23,ink,true);title.setMaxLines(1);title.setAutoSizeTextTypeUniformWithConfiguration(12,23,1,android.util.TypedValue.COMPLEX_UNIT_SP);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView refresh=button("↻",()->sync(true));refresh.setContentDescription("Refresh server data");header.addView(refresh,new LinearLayout.LayoutParams(dp(48),dp(48)));header.addView(button(night?"☀":"◐",()->{saveScroll();Connection.prefs(this).edit().putBoolean("native_night",!night).apply();theme();build();}),new LinearLayout.LayoutParams(dp(48),dp(48)));add(root,header);
        LinearLayout contextBar=row();contextBar.setPadding(dp(10),0,dp(10),0);scopeSelector=spinner(new String[]{"Managed","Original paper","Original archive"},accountScope.equals("Original account")?"Original paper":accountScope.equals("Original archive")?"Original archive":"Managed");contextBar.addView(scopeSelector,new LinearLayout.LayoutParams(-1,-2));add(root,contextBar);scopeSelector.setContentDescription("Select account history");scopeSelector.setOnItemSelectedListener(selectedListener(index->{if(bindingScope)return;String next=new String[]{"Managed population","Original account","Original archive"}[index];if(next.equals(accountScope))return;saveScroll();accountScope=next;chartState=null;go(index==0?"home":index==1?"paper":"archive");}));
