    private String connectionDiagnostics(){StringBuilder b=new StringBuilder("Selected origin: "+repo.origin()+"\nExpected private endpoint: http://localhost:8790\nOwner pause: "+(ownerPaused()?"active, verified":"last known "+(ownerPauseVeto()?"active":"unknown")+"; offline cache is not a live answer")+"\nAPI compatibility: "+("2.0".equals(repo.object(READINESS).optString("contract_version"))?"saved v2.0 readiness":"unknown / legacy")+"\n");
        for(String path:new java.util.LinkedHashSet<>(Arrays.asList(READINESS,SUMMARY,TERMINAL,STATE,statusResource()))){ResourceHealth.Snapshot h=repo.health(path);b.append(path.substring(0,path.indexOf('?')<0?path.length():path.indexOf('?'))).append(" · attempt ").append(date(h.lastAttemptMs)).append(" · success ").append(date(h.lastSuccessMs)).append(" · ").append(h.requesting?"loading":h.error!=null?"unavailable":"unknown or saved").append(" · retry ").append(date(h.nextRetryMs)).append('\n');}
        return b+"\nNext: open your existing Termius connection and verify the localhost 8790 forward. If owner pause is active, leave it paused. These diagnostics do not start the backend. Request ID: unavailable (legacy routes). Source times appear on each observed instrument.";
    }
