    private void startStop(boolean start){final String origin=repo.origin();if(!online()){toast("Connect before changing trading state. No financial actions are queued offline.");return;}JSONObject cfg=obj(summary(),"settings");new AlertDialog.Builder(this).setTitle(start?"Start configured bots?":"Stop bots?").setMessage(start?"Existing selected bots resume with their current capital and holdings. New bots use the saved launch plan and reserve. "+(!cfg.optBoolean("entries_enabled")?"New entries remain paused.":"New entries are enabled."):"Stop suspends decisions, fills and automatic exits. Holdings remain exposed. Pending orders are cancelled by the server; no liquidation is fabricated.").setNegativeButton("Cancel",null).setPositiveButton(start?"Start bots":"Stop bots",(d,w)->guardedPost(origin,start?"/api/population/start":"/api/population/stop",new JSONObject(),(r,e)->{toast(r==null?e:"Portfolio state updated");repo.fetch(SUMMARY,0,true);render();})).show();}
    private void editControl(JSONObject field){String key=field.optString("key");JSONObject cfg=obj(summary(),"settings");if(field.optBoolean("stopped_only")&&cfg.optBoolean("enabled")){toast("Stop the portfolio before changing capital or launch settings.");return;}if(field.optString("type").equals("boolean")){boolean next=!cfg.optBoolean(key);confirmSetting(field,json(key,next),next?"Enable":"Disable");return;}EditText input=edit(field.optString("label"),cfg.isNull(key)?"0":String.valueOf(cfg.optDouble(key)*field.optDouble("display_scale",1)));input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);new AlertDialog.Builder(this).setTitle(field.optString("label")).setView(input).setNegativeButton("Cancel",null).setPositiveButton("Review",(d,w)->{try{double n=Double.parseDouble(input.getText().toString())/field.optDouble("display_scale",1);if(!Double.isFinite(n))throw new IllegalArgumentException();Object value=field.optBoolean("nullable")&&n==0?JSONObject.NULL:n;if(value!=JSONObject.NULL&&(n<field.optDouble("min")||n>field.optDouble("max")))throw new IllegalArgumentException();confirmSetting(field,json(key,value),input.getText().toString());}catch(Exception e){toast("Enter a valid value within the control’s limits.");}}).show();}
    private void confirmSetting(JSONObject f,JSONObject value,String human){final String origin=repo.origin();if(!online()){toast("Connect before changing portfolio controls.");return;}new AlertDialog.Builder(this).setTitle("Apply this control?").setMessage(f.optString("label")+" → "+human+"\nChanges to the future bot allocation do not re-fund existing bots.").setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->guardedPost(origin,"/api/population/settings",value,(r,e)->{toast(r==null?e:"Control saved");repo.fetch(SUMMARY,0,true);if(r!=null)handler.postDelayed(this::render,700);})).show();}
