    private void createAlert(){if(!online()){toast("Connect to create a server alert.");return;}LinearLayout p=vertical();p.setPadding(dp(20),dp(10),dp(20),dp(10));Spinner op=spinner(new String[]{"above","below"},"above");add(p,op);EditText price=edit("Price in instrument currency","");price.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);add(p,price);new AlertDialog.Builder(this).setTitle("Price alert · "+symbol).setView(p).setNegativeButton("Cancel",null).setPositiveButton("Create",(d,w)->{try{double n=Double.parseDouble(price.getText().toString());if(!Double.isFinite(n)||n<=0)throw new IllegalArgumentException();repo.post("/api/alerts",json("symbol",symbol,"op",op.getSelectedItem().toString(),"price",n),(r,e)->{toast(r==null?e:"Alert saved on server");repo.fetch(STATE,0,true);});}catch(Exception e){toast("Enter a positive price.");}}).show();}
    private void paperOrder(){final String orderOrigin=repo.origin();if(!online()){toast("Connect for an order preview. Orders are never queued offline.");return;}final String instrument=symbol;LinearLayout p=vertical();p.setPadding(dp(20),dp(10),dp(20),dp(10));add(p,text("Separate original $100k paper account. This does not place a managed-bot order.",13,muted,false));Spinner side=spinner(new String[]{"buy","sell"},"buy");add(p,side);EditText qty=edit("Quantity","");qty.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);add(p,qty);new AlertDialog.Builder(this).setTitle("Original paper account · preview").setView(p).setNegativeButton("Cancel",null).setPositiveButton("Preview",(d,w)->{try{double n=Double.parseDouble(qty.getText().toString());if(!Double.isFinite(n)||n<=0)throw new IllegalArgumentException();final JSONObject body=json("symbol",instrument,"side",side.getSelectedItem().toString(),"qty",n,"request_id",UUID.randomUUID().toString());repo.post("/api/order-preview",body,(r,e)->{if(r==null){toast(e);return;}confirmOrder(body,r,orderOrigin);});}catch(Exception e){toast("Enter a positive quantity.");}}).show();}
    private void confirmOrder(JSONObject body,JSONObject preview,String orderOrigin){if(!repo.origin().equals(orderOrigin)){toast("Connection changed. Request a new preview for this server.");return;}new AlertDialog.Builder(this).setTitle("Confirm paper "+body.optString("side")+"?").setMessage(body.optString("symbol")+" · "+body.optString("qty")+" units\nIndicative fill "+money(preview,"price","USD")+"\nNotional "+money(preview,"notional","USD")+"\nFee "+money(preview,"fee","USD")+"\nCash after "+money(preview,"cash_after","USD")+"\nThe server will recheck current quotes and risk limits.").setNegativeButton("Cancel",null).setPositiveButton("Confirm paper order",(d,w)->guardedPost(orderOrigin,"/api/orders",body,(r,e)->{if(r!=null){toast("Paper order recorded");repo.fetch(STATE,0,true);}else new AlertDialog.Builder(this).setTitle("Order result needs checking").setMessage(e+"\nCheck history before retrying. A retry below uses the same request ID.").setNegativeButton("Close",null).setPositiveButton("Retry same request",(dialog,which)->confirmOrder(body,preview,orderOrigin)).show();})).show();}
