    private LinearLayout adminArea;private EditText adminDraft;private TextView adminText;private void adminScreen(){LinearLayout c=card(body);section(c,"Your existing Codex session");add(c,text("Commands here can change the project. Unlock with your existing admin passkey. Access is kept only in memory and locks when you leave the app.",13,muted,false));space(c,12);if(adminSession==null){EditText key=edit("Admin passkey","");key.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);add(c,key);add(c,button("Unlock Admin",()->{String value=key.getText().toString();key.setText("");repo.post("/api/admin/unlock",json("passkey",value),(r,e)->{if(r==null){toast(e);return;}adminSession=r.optString("session");render();loadAdmin();});}));return;}
        add(c,button("Lock Admin",this::lockAdmin));adminText=text("Loading session…",13,ink,false);adminText.setTextIsSelectable(true);add(c,adminText);add(c,button("Refresh replies",this::loadAdmin));adminDraft=edit("Command for your linked Codex session","");adminDraft.setMinLines(3);add(c,adminDraft);add(c,button("Review command",()->{String message=adminDraft.getText().toString().trim();if(message.isEmpty())return;new AlertDialog.Builder(this).setTitle("Send command to your Codex session?").setMessage(message+"\n\nThe command waits for the current task to become idle.").setNegativeButton("Cancel",null).setPositiveButton("Send command",(d,w)->repo.post("/api/admin/command",json("session",adminSession,"command",message,"request_id",UUID.randomUUID().toString(),"mode","queue"),(r,e)->{toast(r==null?e:"Command queued");if(r!=null)adminDraft.setText("");loadAdmin();})).show();}));loadAdmin();}
    private void loadAdmin(){if(adminSession==null)return;repo.post("/api/admin/status",json("session",adminSession),(r,e)->{if(r==null){if(adminText!=null)adminText.setText(e);return;}JSONObject session=obj(r,"session");JSONArray messages=arr(session,"messages");StringBuilder b=new StringBuilder(r.optBoolean("connected")?"Connected\n\n":"Session status pending\n\n");for(int i=Math.max(0,messages.length()-12);i<messages.length();i++){JSONObject m=messages.optJSONObject(i);if(m!=null)b.append(m.optString("role")).append("\n").append(m.optString("text",m.optString("content"))).append("\n\n");}JSONArray commands=arr(r,"commands");for(int i=0;i<Math.min(commands.length(),6);i++){JSONObject x=commands.optJSONObject(i);if(x!=null)b.append("Command #").append(x.optInt("id")).append(" · ").append(x.optString("state")).append("\n");}if(adminText!=null)adminText.setText(b.toString());});}
    private void wipePasswords(View v){if(v instanceof EditText&&(((EditText)v).getInputType()&android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD)!=0)((EditText)v).setText("");if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++)wipePasswords(((android.view.ViewGroup)v).getChildAt(i));}
