    private void guardedPost(String expectedOrigin,String path,JSONObject body,DeviceRepository.Reply reply){if(!repo.origin().equals(expectedOrigin)){toast("Connection changed. Review the action again for this server.");return;}repo.post(path,body,reply);}
    private boolean online(){return repo.health(SUMMARY).fresh(System.currentTimeMillis(),45000)&&!ownerPauseVeto();}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    private void openLink(String value){try{Uri u=Uri.parse(value);if(Arrays.asList("http","https").contains(u.getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){toast("No browser available for this link.");}}
    private static String enc(String value){try{return URLEncoder.encode(value,"UTF-8");}catch(java.io.UnsupportedEncodingException e){throw new IllegalStateException(e);}}
    private String fmt(double n,int places){if(!Double.isFinite(n))return "—";NumberFormat f=NumberFormat.getNumberInstance(Locale.US);f.setMaximumFractionDigits(places);return f.format(n);}
    private String money(JSONObject a,String key,String currency){if(!a.has(key)||a.isNull(key))return "—";double n=a.optDouble(key,Double.NaN);if(!Double.isFinite(n))return "—";if(currency.equals("GBp"))return fmt(n,3)+" GBp";return (currency.equals("USD")?"$":currency.equals("INR")?"₹":currency+" ")+fmt(n,Math.abs(n)<1?6:2);}
    private String date(long millis){return millis<=0?"not downloaded":new SimpleDateFormat("dd MMM, HH:mm:ss",Locale.getDefault()).format(new Date(millis));}
    private String source(JSONObject a){long asof=(long)(a.optDouble("asof")*1000),lag=System.currentTimeMillis()-asof;return a.optString("currency")+" · "+a.optString("source",a.optString("provider"))+"\nSource "+date(asof)+(asof==0?"":lag<0?" · future timestamp":lag>300000?" · delayed / closed":" · recent observation");}
    private JSONObject json(Object... values){JSONObject o=new JSONObject();try{for(int i=0;i<values.length;i+=2)o.put(String.valueOf(values[i]),values[i+1]);}catch(JSONException e){throw new IllegalArgumentException(e);}return o;}
    private String readable(JSONObject o){StringBuilder b=new StringBuilder();Iterator<String> keys=o.keys();while(keys.hasNext()){String key=keys.next();Object v=o.opt(key);if(v instanceof JSONObject||v instanceof JSONArray){b.append(key.replace('_',' ')).append("\n").append(String.valueOf(v)).append("\n\n");}else b.append(key.replace('_',' ')).append(": ").append(String.valueOf(v)).append("\n\n");}return b.toString();}
    private class Rows extends BaseAdapter {
        JSONArray items=new JSONArray();String mode="market",signature="";
        void show(JSONArray a,String m){String s=m+a.toString();if(s.equals(signature))return;signature=s;items=a;mode=m;notifyDataSetChanged();}
        public int getCount(){return items.length();}public Object getItem(int p){return items.optJSONObject(p);}public long getItemId(int p){JSONObject a=items.optJSONObject(p);return a==null?p:a.optString("symbol",a.optString("bot",a.optString("id",String.valueOf(p)))).hashCode();}public boolean hasStableIds(){return true;}
        int createdRows=0;
        private class Holder{final LinearLayout root=vertical();final TextView[] lines=new TextView[4];Holder(){createdRows++;root.setPadding(dp(16),dp(15),dp(16),dp(15));root.setMinimumHeight(dp(88));root.setBackground(shape(surface,edge,15));for(int i=0;i<4;i++){lines[i]=text("",i==0?15:13,i==0?ink:muted,i==0);lines[i].setPadding(0,dp(3),0,dp(3));add(root,lines[i]);}root.setTag(this);}}
        public View getView(int position,View reuse,android.view.ViewGroup parent){JSONObject a=items.optJSONObject(position);Holder h=reuse!=null&&reuse.getTag() instanceof MainActivity.Rows.Holder?(Holder)reuse.getTag():new Holder();String[] lines={"Unavailable record","","",""};
            if(a!=null&&mode.equals("market")){lines=new String[]{a.optString("symbol")+" · "+money(a,"price",a.optString("currency","USD")),a.optString("name"),a.optString("kind").replace('_',' ')+" · source "+date((long)(a.optDouble("asof")*1000)),repo.store.item(repo.origin(),a.optString("symbol")).optBoolean("pinned")?"Saved locally":"Downloaded observation"};}
            else if(a!=null&&mode.equals("bot")){JSONObject pop=obj(a,"population");lines=new String[]{a.optString("bot"),obj(pop,"ai_route").optString("model",pop.optString("model")),money(a,"equity_usd","USD")+" · "+money(a,"pnl_usd","USD")+" net",arr(a,"positions").length()+" positions · "+a.optInt("points")+" points · "+a.optInt("closed_episodes")+" closed"};}
            else if(a!=null){lines=new String[]{(a.optString("side",mode)+" "+a.optString("symbol",a.optString("kind"))).trim()+" #"+a.optString("id",a.optString("episode")),a.optString("bot")+" · "+a.optString("state",a.has("points")?a.optString("points")+" pts":"recorded"),a.optString("message",a.optString("reason",a.has("qty")?fmt(a.optDouble("qty"),8)+" units · "+money(a,"usd_total","USD"):"Tap for the complete stored record")),"Saved evidence"};}
            for(int i=0;i<4;i++){if(!h.lines[i].getText().toString().equals(lines[i]))h.lines[i].setText(lines[i]);h.lines[i].setVisibility(lines[i].isEmpty()?View.GONE:View.VISIBLE);}return h.root;
        }
    }
    private void goBack(){hideKeyboard();if(!back.isEmpty()){saveScroll();route=back.pop();render();sync(false);}else if(!route.equals("home")){route="home";render();sync(false);}else moveTaskToBack(true);}
    private void hideKeyboard(){getSystemService(InputMethodManager.class).hideSoftInputFromWindow(content.getWindowToken(),0);}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){goBack();}
    private void dispatchIntent(){if(storageRecovery)return;String eventOrigin=getIntent().getStringExtra("event_origin");if(eventOrigin!=null&&!eventOrigin.equals(repo.origin())){getIntent().removeExtra("route");getIntent().removeExtra("event_origin");toast("This notification belongs to another saved server. Select that connection to view its records.");return;}long eventId=getIntent().getLongExtra("event_id",-1);if(eventOrigin!=null&&eventId>=0)repo.store.eventState(eventOrigin,eventId,"read");getIntent().removeExtra("event_origin");getIntent().removeExtra("event_id");String target=getIntent().getStringExtra("route");if(target!=null){getIntent().removeExtra("route");if(!Arrays.asList("home","markets","bots","activity","more","alerts","settings","research","demo","chat","portfolio","news","daytrader","roster").contains(target))target="activity";go(target.equals("demo")?"archive":target.equals("chat")?"research":target.equals("portfolio")?"paper":target);if(eventOrigin!=null&&eventId>=0)showText("Saved notification · "+eventOrigin,repo.store.eventDetails(eventOrigin,eventId)+"\nRead on this device; no server acknowledgement or financial action.");}}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);dispatchIntent();}
    private void restoreScreen(Bundle in){
        route=in.getString("route","home");symbol=in.getString("symbol","");range=in.getString("range","1D");researchSymbol=in.getString("researchSymbol","RELIANCE.NS");search=in.getString("search","");marketGroup=in.getString("marketGroup","All");activityKind=in.getString("activityKind","fills");activityBot=in.getString("activityBot","");dashboardSymbol=in.getString("dashboardSymbol","");dashboardBot=in.getString("dashboardBot","");activityPage=in.getInt("activityPage",0);directoryQuery=in.getString("directoryQuery","");directoryRegion=in.getString("directoryRegion","India");directoryPage=in.getInt("directoryPage",0);dashboardState=in.getBundle("dashboard");chartState=in.getBundle("chart");ScreenState.restoreScrolls(in,scrollPositions);String[] stack=in.getStringArray("back");if(stack!=null)Collections.addAll(back,stack);
    }
    @Override protected void onSaveInstanceState(Bundle b){if(storageRecovery){super.onSaveInstanceState(b);return;}saveScroll();super.onSaveInstanceState(b);b.putString("stateOrigin",repo.origin());b.putString("accountScope",accountScope);ScreenState.strings(b,route,symbol,range,researchSymbol,search,marketGroup,activityKind,activityBot,directoryQuery,directoryRegion,dashboardSymbol,dashboardBot);b.putInt("activityPage",activityPage);b.putInt("directoryPage",directoryPage);ScreenState.saveScrolls(b,scrollPositions);b.putStringArray("back",back.toArray(new String[0]));b.putBundle("chart",chartState);b.putBundle("dashboard",terminalDashboard==null?dashboardState:terminalDashboard.saveState());}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==81&&result==RESULT_OK&&data!=null&&data.getData()!=null){if(!repo.origin().equals(exportOrigin)){toast("Connection changed; reopen export for this server");return;}try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new java.io.IOException("Export destination unavailable");out.write((storageRecovery?LocalStore.recoverUserData(this,repo.origin()):repo.store.exportUserData(repo.origin())).toString(2).getBytes(StandardCharsets.UTF_8));toast("Exported local records to your selected private destination");}catch(Exception e){toast("Export failed; local records are preserved");}}}
    private void enableNotifications(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},7);return;}Connection.prefs(this).edit().putBoolean("notifications",true).apply();startForegroundService(new Intent(this,NotificationService.class));if(route.equals("settings"))render();}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==7){if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)enableNotifications();else toast("Notification permission denied. The monitor is off; saved alerts remain available.");}}
    @Override protected void onResume(){super.onResume();if(storageRecovery)return;resumed=true;if(route.equals("admin")&&adminSession==null)render();updateData();handler.removeCallbacks(tick);handler.post(tick);repo.fetch("/api/health",0,true);if(Connection.prefs(this).getBoolean("notifications",false)&&getSystemService(NotificationManager.class).areNotificationsEnabled())startForegroundService(new Intent(this,NotificationService.class));}
    @Override protected void onPause(){saveScroll();resumed=false;handler.removeCallbacks(tick);super.onPause();}
    @Override protected void onStop(){wipePasswords(root);lockAdmin();super.onStop();}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);repo.close();super.onDestroy();}
